// Automatic storage duration (block scope)
void example() {
    int x = 10;              // Automatic duration
    register int y = 20;     // Automatic duration (register is a hint)

    if (condition) {
        int z = 30;          // z's lifetime: creation -> end of if-block
    }  // z destroyed here

    // z is out of scope here
}  // x, y destroyed here in reverse order (y, then x)

// NOT automatic duration:
static int s = 5;      // Static storage duration
extern int e;          // Refers to external variable
thread_local int t;    // Thread storage duration

code_example:
#include <iostream>
#include <fstream>
#include <memory>

class Resource {
public:
    Resource(const char* name) : name_(name) {
        std::cout << "  " << name_ << " acquired\n";
    }
    ~Resource() {
        std::cout << "  " << name_ << " released\n";
    }
private:
    const char* name_;
};

void demonstrate_automatic_lifetime() {
    std::cout << "Entering function\n";

    Resource r1("Resource1");  // Automatic duration
    Resource r2("Resource2");  // Automatic duration

    if (true) {
        Resource r3("Resource3");  // Block-scoped automatic
        std::cout << "  Inside if-block\n";
    }  // r3 destroyed here (end of if-block)

    std::cout << "After if-block\n";

    // RAII idiom: file automatically closed when leaving scope
    {
        std::ofstream file("test.txt");
        file << "RAII ensures cleanup\n";
    }  // file destructor closes the file automatically

    std::cout << "Leaving function\n";
}  // r2, r1 destroyed here in REVERSE order

// Side effects prevent elimination
void side_effect_example() {
    Resource unused("UnusedResource");
    // Even though 'unused' is never used, the compiler MUST NOT
    // eliminate it because the destructor has side effects (output).
}  // unused destroyed here (side effect: prints "released")

int main() {
    std::cout << "=== Automatic Storage Duration Demo ===\n\n";
    demonstrate_automatic_lifetime();
    std::cout << "\n";
    side_effect_example();

    return 0;
}

// Output:
// === Automatic Storage Duration Demo ===
//
// Entering function
//   Resource1 acquired
//   Resource2 acquired
//   Resource3 acquired
//   Inside if-block
//   Resource3 released      <- Destroyed at end of if-block
// After if-block
// Leaving function
//   Resource2 released      <- Destroyed in reverse order
//   Resource1 released
//
//   UnusedResource acquired
//   UnusedResource released <- NOT optimized away (side effects)
